pub fn coalesce(xs: &[Interval]) -> Vec<Interval> {
    let mut out = Vec::new();
    for x in xs {
        if let Some(last) = out.last_mut() {
            if last.contig == x.contig && x.start <= last.end {
                last.end = last.end.max(x.end);
                last.depth = last.depth.saturating_add(x.depth);
                continue;
            }
        }
        out.push(x.clone());
    }
    out
}
```

